fun frequencySort(s: String): String {
    return s.groupingBy { it }.eachCount()
        .entries
        .sortedByDescending { it.value }
        .flatMap { (ch, n) -> List(n) { ch } }
        .joinToString("")
}

fun frequencySortBuckets(s: String): String {
    val counts = s.groupingBy { it }.eachCount()
    val buckets = Array(s.length + 1) { StringBuilder() }
    for ((ch, n) in counts) buckets[n].append(ch)
    val out = StringBuilder()
    for (n in buckets.indices.reversed()) {
        for (ch in buckets[n]) repeat(n) { out.append(ch) }
    }
    return out.toString()
}

