fun insertInterval(intervals: List<IntArray>, newInterval: IntArray): List<IntArray> {
    val out = mutableListOf<IntArray>()
    var (start, end) = newInterval
    var i = 0
    while (i < intervals.size && intervals[i][1] < start) out += intervals[i++]
    while (i < intervals.size && intervals[i][0] <= end) {
        start = minOf(start, intervals[i][0])
        end = maxOf(end, intervals[i][1])
        i++
    }
    out += intArrayOf(start, end)
    while (i < intervals.size) out += intervals[i++]
    return out
}

