fun minMeetingRooms(intervals: Array<IntArray>): Int {
    val sorted = intervals.sortedBy { it[0] }
    val ends = java.util.PriorityQueue<Int>()   // end times of busy rooms
    for ((s, e) in sorted) {
        if (ends.isNotEmpty() && ends.peek() <= s) ends.poll()
        ends.add(e)
    }
    return ends.size
}

