fun largestRectangleArea(heights: IntArray): Int {
    val stack = ArrayDeque<Int>()
    var best = 0
    val h = heights + 0   // sentinel flushes the stack
    for (i in h.indices) {
        while (stack.isNotEmpty() && h[stack.last()] >= h[i]) {
            val top = stack.removeLast()
            val left = if (stack.isEmpty()) -1 else stack.last()
            best = maxOf(best, h[top] * (i - left - 1))
        }
        stack.addLast(i)
    }
    return best
}

