fun evalRPN(tokens: List<String>): Int {
    val st = ArrayDeque<Int>()
    for (t in tokens) {
        when (t) {
            "+" -> { val b = st.removeLast(); val a = st.removeLast(); st.addLast(a + b) }
            "-" -> { val b = st.removeLast(); val a = st.removeLast(); st.addLast(a - b) }
            "*" -> { val b = st.removeLast(); val a = st.removeLast(); st.addLast(a * b) }
            "/" -> { val b = st.removeLast(); val a = st.removeLast(); st.addLast(a / b) }
            else -> st.addLast(t.toInt())
        }
    }
    return st.last()
}

