fun kClosest(points: Array<IntArray>, k: Int): Array<IntArray> {
    val dist = { p: IntArray -> p[0] * p[0] + p[1] * p[1] }
    val heap = java.util.PriorityQueue(
        compareByDescending<IntArray> { dist(it) }.thenBy { it[0] }.thenBy { it[1] }
    )
    for (p in points) {
        heap.add(p)
        if (heap.size > k) heap.poll()
    }
    return heap.toTypedArray()
}

